insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('f8d8bwnmba', 'daily:wuerzburg-dom:1610-michael-kern-the-younger-pulpit-of-w-rzburg-cathedral', 'Pulpit of Würzburg Cathedral', 'Michael Kern the Younger', 1610, '1609–1610', null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/f8d8bwnmba.jpg', 'Michael Kern the Younger carved this pulpit in 1609 and 1610. For centuries the sermon came from up here, above the heads of the congregation.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('unmv9rqja6', 'daily:wuerzburg-dom:1981-andreas-moritz-menorah', 'Menorah', 'Andreas Moritz', 1981, null, null, 'metal', 'Würzburg Cathedral (Kiliansdom)', 3, 'object', 'https://nambatu.github.io/circart-preview/art/unmv9rqja6.jpg', 'The seven-branched candelabrum stands in the middle of the nave. Andreas Moritz made it in 1981.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('2hat3rgzjg', 'daily:wuerzburg-dom:1499-tilman-riemenschneider-tomb-of-prince-bishop-rudolf-von-scheren', 'Tomb of Prince-Bishop Rudolf von Scherenberg', 'Tilman Riemenschneider', 1499, '1496–1499', null, 'marble', 'Würzburg Cathedral (Kiliansdom)', 2, 'sculpture', 'https://nambatu.github.io/circart-preview/art/2hat3rgzjg.jpg', 'Rudolf von Scherenberg died in 1495, and Riemenschneider got the commission a year later. The marble monument went up in 1499 and shows the bishop as a very old man, wrinkles and all.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('38up9vv29h', 'daily:wuerzburg-dom:1623-michael-kern-attributed-tomb-of-jakob-baur-von-eiseneck', 'Tomb of Jakob Baur von Eiseneck', 'Michael Kern (attributed)', 1623, '1623, attributed to Michael Kern', null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/38up9vv29h.jpg', 'Jakob Baur von Eiseneck was a colonel in the prince-bishop''s service. He died in July 1621 near Rozvadov in Bohemia, early in the Thirty Years'' War, and his tomb followed in 1623.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('d8dw8kcehs', 'daily:wuerzburg-dom:1279-master-eckart-of-worms-baptismal-font', 'Baptismal font', 'Master Eckart of Worms', 1279, null, null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'object', 'https://nambatu.github.io/circart-preview/art/d8dw8kcehs.jpg', 'Master Eckart from Worms made this font in 1279. Its sides are covered with figures and scenes, so it is worth walking all the way round it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('hs4nuryjuw', 'daily:wuerzburg-dom:1706-giovanni-pietro-magni-stucco-ceiling-of-the-crossing', 'Stucco ceiling of the crossing', 'Giovanni Pietro Magni', 1706, '1701–1706', 'Baroque', 'stucco', 'Würzburg Cathedral (Kiliansdom)', 3, 'architecture', 'https://nambatu.github.io/circart-preview/art/hs4nuryjuw.jpg', 'Giovanni Pietro Magni and a team of stucco workers from Ticino covered the church in baroque decoration between 1701 and 1706. The plain walls of the old church disappeared under swirls of white and gold.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('smb836nzqh', 'daily:wuerzburg-dom:1420-unknown-master-piet', 'Pietà', 'Unknown master', 1420, 'around 1410–1420 (sources differ)', 'International Gothic', null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/smb836nzqh.jpg', 'Mary holds her dead son on her lap. The sources date this Pietà to around 1410 to 1420 and name no sculptor.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('u8kyytsg6y', 'daily:wuerzburg-dom:1967-otto-sonnleitner-kilian-portal', 'Kilian Portal', 'Otto Sonnleitner', 1967, null, null, 'portal', 'Würzburg Cathedral (Kiliansdom)', 3, 'architecture', 'https://nambatu.github.io/circart-preview/art/u8kyytsg6y.jpg', 'Otto Sonnleitner made this portal in 1967, the year the rebuilt cathedral was consecrated again. Since then the church has been dedicated to Kilian and his companions.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('esdap5vn63', 'daily:wuerzburg-dom:1736-balthasar-neumann-sch-nborn-chapel', 'Schönborn Chapel', 'Balthasar Neumann', 1736, '1721–1736', 'Baroque', null, 'Würzburg Cathedral (Kiliansdom)', 2, 'architecture', 'https://nambatu.github.io/circart-preview/art/esdap5vn63.jpg', 'Balthasar Neumann began the burial chapel of the Schönborn family in 1721. The shell stood by 1724, and the chapel was finished in 1736.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7acmeaj58r', 'daily:wuerzburg-dom:1075-bishops-bruno-and-adalbero-w-rzburg-cathedral', 'Würzburg Cathedral', 'Bishops Bruno and Adalbero', 1075, 'built 1040–1075', null, 'building', 'Würzburg Cathedral (Kiliansdom)', 2, 'architecture', 'https://nambatu.github.io/circart-preview/art/7acmeaj58r.jpg', 'Bishop Bruno started the church in 1040, and it was finished under Bishop Adalbero in 1075. Two older cathedrals had stood here before it, and both were damaged by fire.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-07', 'wuerzburg-dom', 'One cathedral, many centuries', 'Ein Dom, viele Jahrhunderte', 'Today we walk through Würzburg Cathedral. Nearly a thousand years of art stand side by side in it, from the Middle Ages to after the war. We start at the pulpit and walk down the middle of the nave towards a tall candelabrum.', 'Heute gehen wir durch den Würzburger Dom. Darin stehen fast tausend Jahre Kunst nebeneinander, vom Mittelalter bis nach dem Krieg. Wir beginnen an der Kanzel und gehen durch die Mitte des Langhauses auf einen hohen Leuchter zu.', 'On 16 March 1945 bombs and fire hit the cathedral, and in February 1946 its north wall collapsed. The rebuilt church was consecrated again on 6 May 1967. That is why old and new art stand so close together here today.', 'Am 16. März 1945 trafen Bomben und Feuer den Dom, und im Februar 1946 stürzte seine Nordwand ein. Am 6. Mai 1967 wurde die wiederaufgebaute Kirche neu geweiht. Deshalb stehen alte und neue Kunst hier heute so dicht beieinander.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 0, 'f8d8bwnmba', null, null, 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 1, 'unmv9rqja6', 'Now walk along the pillars on the left, where the prince-bishops keep watch.', 'Geh jetzt an den Pfeilern links entlang, wo die Fürstbischöfe Wache halten.', 'Photo: José Luiz, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 2, '2hat3rgzjg', 'Riemenschneider lived and worked in Würzburg, and he is buried in the city too. A few pillars on, a soldier waits.', 'Riemenschneider lebte und arbeitete in Würzburg und ist auch hier begraben. Ein paar Pfeiler weiter wartet ein Soldat.', 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 3, '38up9vv29h', 'It was probably carved by Michael Kern, from the same family of sculptors as the pulpit. Now cross over to the font, where the city''s children are baptised.', 'Vermutlich stammt es von Michael Kern, aus derselben Bildhauerfamilie wie die Kanzel. Jetzt geht es hinüber zum Taufbecken, an dem die Kinder der Stadt getauft werden.', 'Photo: Nilaxus, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 4, 'd8dw8kcehs', 'From the font we look straight up, to the white ceiling over the crossing.', 'Vom Taufbecken aus schauen wir direkt nach oben, zur weißen Decke über der Vierung.', 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 5, 'hs4nuryjuw', 'Below all that white and gold sits a quiet figure of grief in front of a golden wall.', 'Unter all dem Weiß und Gold sitzt eine stille Figur der Trauer vor einer goldenen Wand.', 'Photo: José Luiz, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 6, 'smb836nzqh', 'Now we step outside for a moment, to the side door on Kiliansplatz.', 'Jetzt gehen wir kurz hinaus, zum Seitenportal am Kiliansplatz.', 'Photo: Klaus Bärwinkel, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 7, 'u8kyytsg6y', 'Back inside, the north transept leads into a chapel built for one powerful family.', 'Zurück drinnen führt das nördliche Querhaus in eine Kapelle, die für eine mächtige Familie gebaut wurde.', 'Photo: Dietmar Rabich, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 8, 'esdap5vn63', 'Through the chapel we leave the cathedral. Turn around one last time and look at the whole church.', 'Durch die Kapelle verlassen wir den Dom. Dreh dich ein letztes Mal um und schau dir die ganze Kirche an.', 'Photo: Dguendel, CC BY 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 9, '7acmeaj58r', 'And that is the end of our walk.', 'Damit endet unser Rundgang.', 'Photo: Imaschke, CC BY-SA 4.0');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7drh4hwm49', 'daily:written-out:1705-maria-sibylla-merian-spiders-ants-and-a-hummingbird-on-a-guav', 'Spiders, ants and a hummingbird on a guava branch (Metamorphosis insectorum Surinamensium)', 'Maria Sibylla Merian', 1705, 'published in Amsterdam in 1705', null, 'hand-coloured engraving', 'Metamorphosis insectorum Surinamensium (book)', 2, 'drawing', 'https://nambatu.github.io/circart-preview/art/7drh4hwm49.jpg', 'Maria Sibylla Merian sailed to Suriname with her daughter Dorothea to watch insects grow up on their own plants. Back in Amsterdam she published her big book about them in 1705.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('4uwrrhee7q', 'daily:written-out:1555-sofonisba-anguissola-the-chess-game', 'The Chess Game', 'Sofonisba Anguissola', 1555, null, 'Mannerism', 'oil on canvas', 'National Museum, Poznań', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/4uwrrhee7q.jpg', 'Sofonisba Anguissola painted three of her sisters at a game of chess while a maid looks on. She signed and dated the picture on the edge of the chessboard.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('mj9ubupv5k', 'daily:written-out:1907-hilma-af-klint-the-ten-largest-no-7-adulthood', 'The Ten Largest, No. 7, Adulthood', 'Hilma af Klint', 1907, null, 'Abstract art', 'tempera on paper mounted on canvas', 'Hilma af Klint Foundation, Stockholm', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/mj9ubupv5k.jpg', 'This painting is more than three metres tall. It belongs to a series of ten about the ages of a human life, from childhood to old age.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('g9dab98dr3', 'daily:written-out:1630-judith-leyster-self-portrait', 'Self-Portrait', 'Judith Leyster', 1630, 'about 1630', 'Dutch Golden Age', 'oil on canvas', 'National Gallery of Art, Washington', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/g9dab98dr3.jpg', 'Judith Leyster turns round from her easel as if you had just walked into her studio. She was one of very few women in the Haarlem painters'' guild and had pupils of her own.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7a5wukj2sf', 'daily:written-out:1855-rosa-bonheur-the-horse-fair', 'The Horse Fair', 'Rosa Bonheur', 1855, '1852–1855', 'Realism', 'oil on canvas', 'The Metropolitan Museum of Art, New York', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/7a5wukj2sf.jpg', 'The canvas is about five metres wide. To study the horses at the Paris horse market, Rosa Bonheur went there in men''s clothes, which in her day needed a police permit.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('rh87rnegar', 'daily:written-out:1577-lavinia-fontana-self-portrait-at-the-clavichord-with-a-s', 'Self-Portrait at the Clavichord with a Servant', 'Lavinia Fontana', 1577, null, 'Mannerism', 'oil on canvas', 'Accademia Nazionale di San Luca, Rome', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/rh87rnegar.jpg', 'Lavinia Fontana shows herself playing music while a maid holds the sheet music. The picture says: this painter is also an educated young woman.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('ra4mnf79wu', 'daily:written-out:1772-johan-zoffany-the-academicians-of-the-royal-academy', 'The Academicians of the Royal Academy', 'Johan Zoffany', 1772, '1771–1772', null, 'oil on canvas', 'Royal Collection, Windsor', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/ra4mnf79wu.jpg', 'The members of the new Royal Academy in London gather around a nude model in the life class. Two founding members are women, Angelica Kauffman and Mary Moser, but they only appear as small portraits on the wall.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('dm8kz25pp6', 'daily:written-out:1639-artemisia-gentileschi-self-portrait-as-the-allegory-of-paintin', 'Self-Portrait as the Allegory of Painting', 'Artemisia Gentileschi', 1639, '1638–1639', 'Baroque', 'oil on canvas', 'Royal Collection, Hampton Court Palace', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/dm8kz25pp6.jpg', 'Artemisia Gentileschi painted herself as the figure of Painting, brush in hand and hard at work. She probably made it during her stay in England, and King Charles I owned it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('tk34mfb7dj', 'daily:written-out:1872-berthe-morisot-the-cradle', 'The Cradle', 'Berthe Morisot', 1872, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/tk34mfb7dj.jpg', 'Berthe Morisot painted her sister Edma watching over her sleeping baby, Blanche. The picture hung in the first Impressionist exhibition.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('8cyrccbgzw', 'daily:written-out:1782-lisabeth-vig-e-le-brun-self-portrait-in-a-straw-hat', 'Self-Portrait in a Straw Hat', 'Élisabeth Vigée Le Brun', 1782, 'after 1782', null, 'oil on canvas', 'National Gallery, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/8cyrccbgzw.jpg', 'On a trip to Flanders Élisabeth Vigée Le Brun saw Rubens'' portrait of a woman in a straw hat and painted her own answer to it. She became Queen Marie Antoinette''s favourite portrait painter.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-08', 'written-out', 'Written out of the picture', 'Aus dem Bild gedrängt', 'Today''s ten pictures were all made by women, except one, and that one tells you a lot. Each of these women was famous in her day and was then pushed to the edge of the frame. Your start card is a page from Maria Sibylla Merian''s insect book. The first picture to place shows three sisters at a chessboard.', 'Die zehn Bilder von heute haben alle Frauen gemacht, bis auf eins, und genau das verrät viel. Jede dieser Frauen war zu Lebzeiten berühmt und wurde danach an den Bildrand gedrängt. Deine Startkarte ist eine Seite aus Maria Sibylla Merians Insektenbuch. Das erste Bild zum Einordnen zeigt drei Schwestern am Schachbrett.', 'Every woman today was celebrated in her lifetime, and many of them then went missing from the big art history books. Museums around the world are now bringing them back into the picture, one exhibition at a time.', 'Jede Frau von heute wurde zu Lebzeiten gefeiert, und viele verschwanden danach aus den großen Kunstgeschichtsbüchern. Museen auf der ganzen Welt holen sie jetzt zurück ins Bild, eine Ausstellung nach der anderen.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 0, '7drh4hwm49', null, null, 'Maria Sibylla Merian, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 1, '4uwrrhee7q', 'Sofonisba went on to work at the Spanish court and painted the royal family. Our next painter chose to hide her boldest pictures herself.', 'Sofonisba arbeitete dann am spanischen Hof und malte die Königsfamilie. Unsere nächste Malerin hat ihre kühnsten Bilder selbst versteckt.', 'Sofonisba Anguissola, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 2, 'mj9ubupv5k', 'Hilma af Klint asked that her abstract work stay hidden for twenty years following her death, so the world met it very late. The next painter vanished in another way: under a famous man''s name.', 'Hilma af Klint wollte, dass ihre abstrakten Bilder bis zwanzig Jahre nach ihrem Tod verborgen bleiben, und so lernte die Welt sie erst sehr spät kennen. Die nächste Malerin verschwand auf andere Weise: unter dem Namen eines berühmten Mannes.', 'Hilma af Klint, public domain (photo: Hilma af Klint Foundation, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 3, 'g9dab98dr3', 'For a long time Leyster''s pictures were sold as works by Frans Hals, and only in 1893 was she rediscovered. The next painter made sure nobody could overlook her: she painted big.', 'Lange wurden Leysters Bilder als Werke von Frans Hals verkauft, erst 1893 wurde sie wiederentdeckt. Die nächste Malerin sorgte dafür, dass niemand sie übersehen konnte: Sie malte riesig.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 4, '7a5wukj2sf', 'Rosa Bonheur became the first woman artist to receive the Legion of Honour. From the noisy horse market we go to a quiet room, where a young woman sits at a keyboard.', 'Rosa Bonheur bekam als erste Künstlerin das Kreuz der Ehrenlegion. Vom lauten Pferdemarkt geht es in einen stillen Raum, in dem eine junge Frau an einem Tasteninstrument sitzt.', 'The Metropolitan Museum of Art, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 5, 'rh87rnegar', 'Lavinia Fontana went on to Rome as a sought-after portrait painter while raising a large family. Next comes the one picture by a man today. Look closely at who is missing.', 'Lavinia Fontana zog als gefragte Porträtmalerin nach Rom und zog nebenbei eine große Familie groß. Jetzt kommt das einzige Bild eines Mannes heute. Schau genau hin, wer fehlt.', 'Lavinia Fontana, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 6, 'ra4mnf79wu', 'A lady was not allowed into the life class, so the two women could only hang on the wall. The next woman put herself right in the middle of the picture, as Painting itself.', 'Eine Dame durfte beim Aktzeichnen nicht dabei sein, also konnten die beiden Frauen nur an der Wand hängen. Die nächste Frau hat sich mitten ins Bild gesetzt, als die Malerei selbst.', 'Johan Zoffany, public domain (Royal Collection, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 7, 'dm8kz25pp6', 'Artemisia was famous across Europe in her lifetime, and then she almost disappeared from the books. Our next painter turned her brush on her own family.', 'Artemisia war zu Lebzeiten in ganz Europa berühmt und verschwand danach fast aus den Büchern. Unsere nächste Malerin hat ihre eigene Familie gemalt.', 'Artemisia Gentileschi, public domain (Royal Collection, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 8, 'tk34mfb7dj', 'Morisot took part in nearly every Impressionist exhibition. Our final picture is a self-portrait in a straw hat.', 'Morisot war bei fast allen Ausstellungen der Impressionisten dabei. Unser letztes Bild ist ein Selbstporträt mit Strohhut.', 'Musée d''Orsay, public domain (Google Art Project, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 9, '8cyrccbgzw', 'And that is the end of our gallery.', 'Damit endet unser Rundgang durch die Galerie.', 'National Gallery, London, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('wwgwkshzxs', 'daily:saint-martin:1567-pieter-bruegel-the-elder-the-wine-of-saint-martin-s-day', 'The Wine of Saint Martin''s Day', 'Pieter Bruegel the Elder', 1567, '1566–1567 (Prado); Wikipedia gives c. 1565–1568', 'Northern Renaissance', 'glue-size tempera on linen', 'Museo del Prado, Madrid', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/wwgwkshzxs.jpg', 'A whole village crowds round a barrel of new wine, and somewhere in the throng St Martin quietly shares his cloak. Experts found traces of Bruegel''s signature on it in 2010, and the Prado bought the picture that same year.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('uxjczc23qj', 'daily:saint-martin:1317-simone-martini-saint-martin-shares-his-cloak-with-a-beg', 'Saint Martin Shares His Cloak with a Beggar', 'Simone Martini', 1317, 'the chapel frescoes are undated; about 1313–1318 (Wikipedia), about 1316–1317 (Key to Umbria)', 'Sienese School', 'fresco', 'San Martino Chapel, Lower Basilica of San Francesco, Assisi', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/uxjczc23qj.jpg', 'This scene opens a series of ten frescoes about Martin''s life in a chapel of the Lower Basilica in Assisi. A cardinal paid for the chapel, but Simone Martini neither signed nor dated his paintings.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('8267g92wvy', 'daily:saint-martin:1599-el-greco-saint-martin-and-the-beggar', 'Saint Martin and the Beggar', 'El Greco', 1599, '1597–1599', 'Mannerism', 'oil on canvas', 'National Gallery of Art, Washington', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/8267g92wvy.jpg', 'Martín Ramírez, who shared the saint''s name, ordered this picture for his chapel of San José in Toledo. It stayed there for about three hundred years before it went to America.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('t3n2tp76g6', 'daily:saint-martin:1240-naumburg-master-attributed-bassenheim-rider', 'Bassenheim Rider', 'Naumburg Master (attributed)', 1240, 'about 1240: the plaque in Bassenheim says 1239, the regional tourism site says the master worked in Mainz around 1250', null, 'sandstone relief', 'Parish church of St Martin, Bassenheim', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/t3n2tp76g6.jpg', 'This grey sandstone relief is attributed to the Naumburg Master, one of the great sculptors of the Middle Ages. Martin cuts his cloak with his sword while the beggar already holds on to it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('f6xavxx6wj', 'daily:saint-martin:1900-gebhard-fugel-saint-martin-and-the-beggar', 'Saint Martin and the Beggar', 'Gebhard Fugel', 1900, '1900 (Commons); Panorama Altötting dates his murals in the Wangen town church to 1899', null, 'ceiling painting', 'Parish church of St Martin, Wangen im Allgäu', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/f6xavxx6wj.jpg', 'Gebhard Fugel painted this scene on the ceiling of St Martin''s church in Wangen im Allgäu. He was born near Ravensburg, not far away, and painted churches in southern Germany and Austria.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('gnznszywvc', 'daily:saint-martin:1475-martin-schongauer-saint-martin-dividing-his-cloak', 'Saint Martin Dividing His Cloak', 'Martin Schongauer', 1475, 'about 1475', 'Northern Renaissance', 'engraving', 'National Gallery of Art, Washington', 3, 'drawing', 'https://nambatu.github.io/circart-preview/art/gnznszywvc.jpg', 'This engraving is only about fifteen centimetres tall. Because it was printed from an engraved metal plate, the same little Martin could be printed again and again.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('2vezsr9kp2', 'daily:saint-martin:1620-anthony-van-dyck-saint-martin-dividing-his-cloak', 'Saint Martin Dividing his Cloak', 'Anthony van Dyck', 1620, 'about 1618–1620 (Royal Collection); Wikipedia gives about 1620', 'Baroque', 'oil on canvas', 'Royal Collection, Windsor Castle', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/2vezsr9kp2.jpg', 'Van Dyck painted a smaller version of this scene for the church in Zaventem near Brussels, and it still hangs there. This bigger one, more than two metres wide, belongs to the British Royal Collection.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-11', 'saint-martin', 'Half a cloak', 'Ein halber Mantel', 'Today is St Martin''s Day, and children all over the country walk with lanterns. We follow one moment that artists never got tired of: a young soldier cuts his cloak in half for a freezing beggar. Your start card is a wild village feast in Martin''s honour, and the first picture to place takes you to a chapel in Italy.', 'Heute ist Martinstag, und überall ziehen Kinder mit Laternen durch die Straßen. Wir folgen einem Moment, von dem Künstler nie genug bekamen: Ein junger Soldat teilt seinen Mantel für einen frierenden Bettler. Deine Startkarte ist ein wildes Dorffest zu Martins Ehren, und das erste Bild zum Einordnen führt dich in eine Kapelle in Italien.', 'Every age dressed Martin and his beggar in its own way, but the gesture stayed the same. Tonight his story lives on in lantern walks and in many a roast goose.', 'Jede Zeit hat Martin und seinen Bettler auf ihre eigene Weise gekleidet, doch die Geste blieb dieselbe. Heute Abend lebt seine Geschichte in Laternenumzügen weiter und in so mancher Martinsgans.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 0, 'wwgwkshzxs', null, null, 'Museo del Prado, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 1, 'uxjczc23qj', 'Simone Martini painted Martin''s whole life on these chapel walls. Next we travel to Toledo in Spain, where a man called Martín wanted his patron saint over his altar.', 'Simone Martini hat Martins ganzes Leben an diese Kapellenwände gemalt. Als Nächstes reisen wir nach Toledo in Spanien, wo ein Mann namens Martín seinen Namenspatron über dem Altar haben wollte.', 'Simone Martini, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 2, '8267g92wvy', 'El Greco puts Martin in shining armour on a white horse, high above the beggar. Our next Martin is not painted at all: he is carved in stone.', 'El Greco setzt Martin in glänzender Rüstung auf ein weißes Pferd, hoch über den Bettler. Unser nächster Martin ist gar nicht gemalt: Er ist in Stein gehauen.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 3, 't3n2tp76g6', 'In 1683 the rider came to the village of Bassenheim, and he still lives in its parish church. Now look up: our next Martin rides across a church ceiling in the Allgäu.', '1683 kam der Reiter in das Dorf Bassenheim, und er wohnt bis heute in der Pfarrkirche dort. Jetzt schau nach oben: Unser nächster Martin reitet über eine Kirchendecke im Allgäu.', 'Photo: Lothar Spurzem, CC BY-SA 2.0 de');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 4, 'f6xavxx6wj', 'Fugel also painted a giant panorama of the Crucifixion for Altötting. Our next Martin is tiny by comparison: he fits on a sheet of paper smaller than your hand.', 'Fugel malte auch ein riesiges Panorama der Kreuzigung für Altötting. Unser nächster Martin ist dagegen winzig: Er passt auf ein Blatt Papier, das kleiner ist als deine Hand.', 'Gebhard Fugel, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 5, 'gnznszywvc', 'Schongauer shared his name with the saint, a nice coincidence for this card. Our final Martin comes from Antwerp, a city full of painters.', 'Schongauer trug denselben Vornamen wie der Heilige, ein schöner Zufall für diese Karte. Unser letzter Martin kommt aus Antwerpen, einer Stadt voller Maler.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 6, '2vezsr9kp2', 'And with that, our lantern walk ends.', 'Damit endet unser Laternenumzug.', 'Royal Collection Trust, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('rp9jsftwzf', 'daily:stolen:1633-rembrandt-the-storm-on-the-sea-of-galilee', 'The Storm on the Sea of Galilee', 'Rembrandt', 1633, null, 'Dutch Golden Age', 'oil on canvas', 'Stolen from the Isabella Stewart Gardner Museum, Boston (whereabouts unknown)', 1, 'destroyed_or_lost', 'https://nambatu.github.io/circart-preview/art/rp9jsftwzf.jpg', 'Rembrandt''s only seascape – and nobody has seen it in public for decades. It was stolen in the largest art heist in US history, when thieves posing as police officers walked out of the Gardner Museum with thirteen works. Among the panicking disciples, one man looks straight out at you: Rembrandt himself.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('qfss9crjpx', 'daily:stolen:1503-leonardo-da-vinci-mona-lisa', 'Mona Lisa', 'Leonardo da Vinci', 1503, 'c. 1503-1506', 'High Renaissance', 'oil on poplar', 'Louvre, Paris', 1, 'object', 'https://nambatu.github.io/circart-preview/art/qfss9crjpx.jpg', 'It was a moderately admired picture until 1911, when a Louvre handyman named Vincenzo Peruggia walked out with it under his coat. The empty wall drew larger crowds than the painting ever had, Picasso was questioned as a suspect, and by the time it came back two years later it was the most famous object in the world. Fame was retroactive. Leonardo also never delivered it to whoever commissioned it, carrying it around for over a decade instead.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('g6vx5k7rdm', 'daily:stolen:1893-edvard-munch-the-scream', 'The Scream', 'Edvard Munch', 1893, null, 'Expressionism', 'tempera and crayon on cardboard', 'National Gallery, Oslo', 1, 'object', 'https://nambatu.github.io/circart-preview/art/g6vx5k7rdm.jpg', 'Munch''s diary records walking at sunset when the sky turned blood red and he felt an infinite scream passing through nature, and researchers have suggested the colour came from Krakatoa ash, which produced spectacular red skies over Europe for months. The figure is not screaming but blocking out a scream. In the top left corner, in tiny pencil, someone wrote that it could only have been painted by a madman; 2021 analysis confirmed the handwriting is Munch''s own.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('xpwajjqect', 'daily:stolen:1432-jan-van-eyck-the-ghent-altarpiece', 'The Ghent Altarpiece', 'Jan van Eyck', 1432, null, 'Northern Renaissance', 'oil on panel', 'Saint Bavo Cathedral, Ghent', 2, 'object', 'https://nambatu.github.io/circart-preview/art/xpwajjqect.jpg', 'The most frequently stolen artwork in history, by some distance. It has been burned at, dismembered, ransomed by Napoleon, handed over as a First World War reparation, hidden in an Austrian salt mine by the Nazis and rescued by the Monuments Men. One panel taken in 1934 has never been found and is still represented by a copy. Recent cleaning also removed centuries of overpaint from the Mystic Lamb, revealing an unnervingly humanoid face with forward-set eyes that briefly went viral.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('3w2qrw53zx', 'daily:stolen:1814-francisco-goya-portrait-of-the-duke-of-wellington', 'Portrait of the Duke of Wellington', 'Francisco Goya', 1814, 'painted in 1812 and reworked until 1814 (National Gallery: 1812–14)', 'Romanticism', 'oil on mahogany', 'National Gallery, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/3w2qrw53zx.jpg', 'Goya painted the British general in Madrid, right after Wellington had driven the French army out of the city. When Wellington won more honours, Goya went back to the picture and added them to the uniform.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('cxftepb2uu', 'daily:stolen:1672-johannes-vermeer-the-guitar-player', 'The Guitar Player', 'Johannes Vermeer', 1672, 'not dated; about 1672 (Kenwood, Wikipedia), about 1670–1673 (Essential Vermeer)', 'Dutch Golden Age', 'oil on canvas', 'Kenwood House, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/cxftepb2uu.jpg', 'A young woman looks up from her guitar and smiles at someone we can''t see. When Vermeer died, his widow handed this picture to the family''s baker as a pledge for a large unpaid bread bill.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('cfsqjq6a52', 'daily:stolen:1882-vincent-van-gogh-view-of-the-sea-at-scheveningen', 'View of the Sea at Scheveningen', 'Vincent van Gogh', 1882, 'August 1882', null, 'oil on canvas', 'Van Gogh Museum, Amsterdam', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/cfsqjq6a52.jpg', 'Van Gogh set up his easel on the beach in the middle of a storm. The wind blew so hard that grains of sand stuck in the wet paint, and some of them are still there.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-13', 'stolen', 'Bad luck, good luck', 'Pech und Glück', 'It''s Friday the 13th, so today''s paintings all had a very bad day once: each of them was stolen. Some came home in the strangest ways, and two are still missing. Your start card is a famous empty frame in Boston, and the first picture to place once left the Louvre in Paris without anyone noticing.', 'Heute ist Freitag, der 13., also hatte jedes Bild von heute schon einmal einen richtig schlechten Tag: Alle wurden gestohlen. Manche kamen auf den seltsamsten Wegen zurück, und zwei sind bis heute verschwunden. Deine Startkarte ist ein berühmter leerer Rahmen in Boston, und das erste Bild zum Einordnen verließ einst den Louvre in Paris, ohne dass es jemand bemerkte.', 'Five of today''s works are safely home, and the great altarpiece in Ghent is still waiting for one panel. Rembrandt''s storm is out there somewhere, and in Boston its empty frame still hangs on the wall. Luckily, bad luck doesn''t always last.', 'Fünf der heutigen Werke sind wieder sicher zu Hause, und der große Altar in Gent wartet noch auf eine Tafel. Rembrandts Sturm ist irgendwo da draußen, und in Boston hängt sein leerer Rahmen noch immer an der Wand. Zum Glück hält Pech nicht ewig.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 0, 'rp9jsftwzf', null, null, 'Rembrandt, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 1, 'qfss9crjpx', 'In 1911 a Louvre worker simply carried her out under his coat, and for two years nobody knew where she was. Her disappearance made her the most famous painting in the world. Our next picture was taken on a morning when all of Norway was watching the Olympics.', '1911 trug ein Arbeiter des Louvre sie einfach unter seinem Mantel hinaus, und zwei Jahre lang wusste niemand, wo sie war. Erst durch ihr Verschwinden wurde sie zum berühmtesten Bild der Welt. Unser nächstes Bild verschwand an einem Morgen, an dem ganz Norwegen auf die Olympischen Spiele schaute.', 'Leonardo da Vinci, public domain (C2RMF / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 2, 'g6vx5k7rdm', 'Two men leaned a ladder against the museum wall and were gone in under a minute. They even left a note that thanked the museum for the poor security. Three months on the police had the picture back, unharmed. The next work holds a sad record, because no other artwork has been stolen so often.', 'Zwei Männer lehnten eine Leiter an die Museumswand und waren nach nicht einmal einer Minute wieder weg. Sie hinterließen sogar einen Zettel und bedankten sich für die schlechte Bewachung. Drei Monate danach hatte die Polizei das Bild unversehrt zurück. Das nächste Werk hält einen traurigen Rekord, denn kein anderes Kunstwerk wurde so oft gestohlen.', 'Edvard Munch, public domain (Nasjonalmuseet / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 3, 'xpwajjqect', 'Napoleon''s soldiers carried parts of it off to Paris, and in the Second World War it was hidden deep inside an Austrian salt mine until Allied soldiers found it. One panel was taken in 1934 and never came back, so a copy stands in its place. Our next thief wanted something much smaller, and that was free television.', 'Napoleons Soldaten schleppten Teile davon nach Paris, und im Zweiten Weltkrieg lag der Altar tief in einem österreichischen Salzbergwerk, bis alliierte Soldaten ihn fanden. Eine Tafel wurde 1934 gestohlen und kam nie zurück, deshalb steht an ihrer Stelle eine Kopie. Unser nächster Dieb wollte etwas viel Kleineres, nämlich kostenloses Fernsehen.', 'Jan and Hubert van Eyck, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 4, '3w2qrw53zx', 'The man who confessed was a former bus driver who wanted free TV for pensioners. While the police searched, a copy of the painting even had a cameo in a James Bond film, hanging in the villain''s lair. Next we visit a grand house on the edge of a London park.', 'Gestanden hat ein ehemaliger Busfahrer, der sich kostenloses Fernsehen für Rentner wünschte. Während die Polizei suchte, hatte eine Kopie des Bildes sogar einen Auftritt in einem James-Bond-Film, an der Wand im Versteck des Bösewichts. Als Nächstes besuchen wir ein herrschaftliches Haus am Rand eines Londoner Parks.', 'Francisco Goya, public domain (National Gallery / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 5, 'cxftepb2uu', 'A ransom note demanded that two sisters, jailed for an IRA bombing in London, be moved to a prison in Northern Ireland. Nobody gave in. Ten weeks on, the painting stood in a London churchyard, leaning against a gravestone and wrapped in newspaper. For our last picture we climb onto a museum roof in Amsterdam.', 'In einem Erpresserbrief hieß es, zwei Schwestern sollten nach Nordirland verlegt werden, die wegen eines IRA-Bombenanschlags in London im Gefängnis saßen. Niemand gab nach. Zehn Wochen danach stand das Bild auf einem Londoner Kirchhof, an einen Grabstein gelehnt und in Zeitungspapier gewickelt. Für unser letztes Bild klettern wir auf ein Museumsdach in Amsterdam.', 'Johannes Vermeer, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 6, 'cfsqjq6a52', 'Two thieves climbed a ladder to the museum roof, smashed a window and left with this picture and one more. It took fourteen years until Italian police found both of them near Naples, in the hands of the Camorra. Today the stormy sea hangs on its wall in Amsterdam again.', 'Zwei Diebe stiegen mit einer Leiter aufs Museumsdach, schlugen ein Fenster ein und nahmen dieses Bild und noch ein weiteres mit. Es dauerte vierzehn Jahre, bis die italienische Polizei beide bei Neapel fand, in den Händen der Camorra. Heute hängt das stürmische Meer wieder an seiner Wand in Amsterdam.', 'Vincent van Gogh, public domain (Van Gogh Museum / Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('wz89wq6adr', 'daily:monet:1877-claude-monet-the-saint-lazare-station', 'The Saint-Lazare Station', 'Claude Monet', 1877, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/wz89wq6adr.jpg', 'Monet got permission to paint inside the busy Paris station and made about a dozen views of it. The story goes that trains were held back and stoked so he could catch the steam. Here the subject is really the smoke and light, with the trains as supporting actors.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('wcaxn6rn33', 'daily:monet:1866-claude-monet-camille-the-woman-in-the-green-dress', 'Camille (The Woman in the Green Dress)', 'Claude Monet', 1866, null, null, 'oil on canvas', 'Kunsthalle Bremen', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/wcaxn6rn33.jpg', 'Monet had planned a huge picnic scene for the Paris Salon, but he could not finish it in time. So he sent this portrait of his model Camille Doncieux instead. The jury accepted it, and the critics were full of praise for its fresh style.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('hwsdjchggp', 'daily:monet:1899-claude-monet-the-japanese-footbridge', 'The Japanese Footbridge', 'Claude Monet', 1899, null, 'Impressionism', 'oil on canvas', 'National Gallery of Art, Washington, D.C.', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/hwsdjchggp.jpg', 'The bridge stood in Monet''s own garden in the village of Giverny. He designed the garden himself and had a small stream diverted to feed the lily pond. He painted this same view twelve times in a single year.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('asreeqmju6', 'daily:monet:1872-claude-monet-impression-sunrise', 'Impression, Sunrise', 'Claude Monet', 1872, null, 'Impressionism', 'oil on canvas', 'Musée Marmottan Monet, Paris', 1, 'object', 'https://nambatu.github.io/circart-preview/art/asreeqmju6.jpg', 'A hostile critic named Louis Leroy wrote a mocking review built around the title, saying that wallpaper in its embryonic state was more finished, and coined Impressionism as an insult. The group adopted it within a couple of years. Astronomers have since analysed the tide, the smoke direction and the sun''s altitude and dated the scene to around 7:35am on 13 November 1872. It was stolen in 1985 and recovered five years later.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('kb7s7myzru', 'daily:monet:1879-claude-monet-camille-monet-on-her-deathbed', 'Camille Monet on Her Deathbed', 'Claude Monet', 1879, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/kb7s7myzru.jpg', 'Camille died in the village of Vétheuil at the age of 32, after a long illness. Monet painted her one last time. He told a friend that he had caught himself studying the colours on her face, and that it had shocked him.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('kekmxvsqbx', 'daily:monet:1875-claude-monet-woman-with-a-parasol-madame-monet-and-he', 'Woman with a Parasol – Madame Monet and Her Son', 'Claude Monet', 1875, null, 'Impressionism', 'oil on canvas', 'National Gallery of Art, Washington, D.C.', 1, 'object', 'https://nambatu.github.io/circart-preview/art/kekmxvsqbx.jpg', 'Monet painted his wife Camille and their son Jean on a windy summer day near Argenteuil. He worked outdoors and fast, probably in a single session of a few hours. You can almost feel the breeze in her veil.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('vnmb2sh6h7', 'daily:monet:1906-claude-monet-water-lilies', 'Water Lilies', 'Claude Monet', 1906, 'signed and dated 1906', 'Impressionism', 'oil on canvas', 'Art Institute of Chicago', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/vnmb2sh6h7.jpg', 'There is no bank, no bridge and no sky in this picture. Monet looks only at the surface of his pond, so the sky and the trees appear just as reflections between the lily pads. He showed 48 of these water pictures together in Paris.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('59xxuxm4qg', 'daily:monet:1894-claude-monet-rouen-cathedral-the-portal-in-full-sunli', 'Rouen Cathedral, the Portal in Full Sunlight', 'Claude Monet', 1894, 'painted in Rouen in 1893, finished in the studio and dated 1894 (Musée d''Orsay)', 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/59xxuxm4qg.jpg', 'Monet rented a room across the square from the cathedral and worked on many canvases at once. He swapped them as the light moved over the stone. This one shows the front in full sunlight, and its other name is "Harmony in Blue and Gold".', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-14', 'monet', 'Monet''s life in eight pictures', 'Monets Leben in acht Bildern', 'Claude Monet was born in Paris on 14 November 1840. Today we follow his life through eight of his own pictures, from a young painter with empty pockets to the gardener of Giverny. Your start card is a railway station full of steam, and the first picture to place shows the woman who would change his life.', 'Claude Monet kam am 14. November 1840 in Paris zur Welt. Heute folgen wir seinem Leben durch acht seiner eigenen Bilder, vom jungen Maler mit leeren Taschen bis zum Gärtner von Giverny. Deine Startkarte ist ein Bahnhof voller Dampf, und das erste Bild zum Einordnen zeigt die Frau, die sein Leben verändern sollte.', 'Monet went on painting his pond until he died in Giverny in 1926, at the age of 86. His house and garden are open to visitors, and the water lilies still bloom there every summer. Happy birthday, Claude.', 'Monet malte seinen Teich, bis er 1926 mit 86 Jahren in Giverny starb. Sein Haus und sein Garten stehen Besuchern offen, und die Seerosen blühen dort noch jeden Sommer. Alles Gute zum Geburtstag, Claude.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 0, 'wz89wq6adr', null, null, 'Claude Monet, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 1, 'wcaxn6rn33', 'The woman in the green dress was a young studio model when she met Monet, and she became his wife. You will meet her again today. Our next picture leaves Paris far behind: a little green bridge over a pond.', 'Die Frau im grünen Kleid war ein junges Malermodell, als sie Monet kennenlernte, und sie wurde seine Frau. Du triffst sie heute noch einmal wieder. Unser nächstes Bild lässt Paris weit hinter sich: eine kleine grüne Brücke über einem Teich.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 2, 'hwsdjchggp', 'In Giverny Monet found the home where he stayed for the rest of his life, and he turned its garden into his favourite subject. For the next picture we go to the harbour of Le Havre, the town where he grew up, on a misty morning.', 'In Giverny fand Monet das Zuhause, in dem er bis an sein Lebensende blieb, und dessen Garten machte er zu seinem liebsten Motiv. Für das nächste Bild gehen wir an einem nebligen Morgen in den Hafen von Le Havre, der Stadt, in der er aufwuchs.', 'Claude Monet, public domain (National Gallery of Art, Washington / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 3, 'asreeqmju6', 'This little harbour view gave a whole movement its name. Fame did not pay the bills, though, and the family often had to borrow money. The next picture is the saddest one he ever painted.', 'Dieser kleine Hafenblick gab einer ganzen Bewegung ihren Namen. Die Rechnungen bezahlte der Ruhm aber nicht, und die Familie musste sich oft Geld leihen. Das nächste Bild ist das traurigste, das er je gemalt hat.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 4, 'kb7s7myzru', 'Monet was left with two sons and very little money. To remember Camille as he knew her, our next picture is full of wind and sunshine: a woman with a parasol on a hill.', 'Monet blieb mit zwei Söhnen und sehr wenig Geld zurück. Damit wir Camille so in Erinnerung behalten, wie er sie kannte, ist unser nächstes Bild voller Wind und Sonne: eine Frau mit Sonnenschirm auf einem Hügel.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 5, 'kekmxvsqbx', 'In many of Monet''s best-known pictures there are no people at all, and that makes this one special. In the next one there is nothing but water and flowers.', 'Auf vielen von Monets bekanntesten Bildern ist gar kein Mensch zu sehen, und das macht dieses hier besonders. Im nächsten gibt es nur noch Wasser und Blüten.', 'Claude Monet, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 6, 'vnmb2sh6h7', 'Monet painted his pond around 250 times, and the canvases grew until they filled whole rooms. But one subject was never enough for him, because what he was really after was the light. Our last picture is the stone front of a great church, and he painted it more than thirty times.', 'Rund 250 Mal malte Monet seinen Teich, und die Leinwände wurden immer größer, bis sie ganze Räume füllten. Ein Motiv allein war ihm aber nie genug, denn eigentlich ging es ihm um das Licht. Unser letztes Bild ist die steinerne Fassade einer großen Kirche, und er malte sie mehr als dreißig Mal.', 'Claude Monet, public domain (Art Institute of Chicago / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 7, '59xxuxm4qg', 'Twenty of the cathedral pictures went on show together in Paris: the same church front in twenty kinds of light. The painter with the empty pockets had become one of the most famous artists in France.', 'Zwanzig der Kathedralenbilder wurden zusammen in Paris ausgestellt: dieselbe Kirchenfassade in zwanzig Arten von Licht. Aus dem Maler mit den leeren Taschen war einer der berühmtesten Künstler Frankreichs geworden.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('jz7qdrkayf', 'daily:skull:1630-pieter-claesz-vanitas-still-life', 'Vanitas Still Life', 'Pieter Claesz', 1630, null, null, 'oil on panel', 'Mauritshuis, The Hague', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/jz7qdrkayf.jpg', 'Everything on this table carries the same message. The light has just gone out, the glass has tipped over and the watch keeps ticking. Claesz put his initials and the date on the book, as if they were written into its pages.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('xs8xx9jzr9', 'daily:skull:1533-hans-holbein-the-younger-the-ambassadors', 'The Ambassadors', 'Hans Holbein the Younger', 1533, null, 'Northern Renaissance', 'oil on oak', 'National Gallery, London', 2, 'object', 'https://nambatu.github.io/circart-preview/art/xs8xx9jzr9.jpg', 'The grey smear across the floor resolves into a perfect human skull if you stand at the lower right edge of the frame, which is exactly where you end up if the painting hangs beside a staircase. Everything in the picture is a status object: globes, sundials, a lute, a Lutheran hymn book. One lute string is broken. It is a portrait of two young men at the height of their powers with death drawn diagonally across the carpet.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('gh9mkbwkze', 'daily:skull:1886-vincent-van-gogh-head-of-a-skeleton-with-a-burning-cigare', 'Head of a Skeleton with a Burning Cigarette', 'Vincent van Gogh', 1886, 'winter 1885–86; the Van Gogh Museum dates it to early 1886', null, 'oil on canvas', 'Van Gogh Museum, Amsterdam', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/gh9mkbwkze.jpg', 'Small as it is, this picture shows how well Van Gogh had learned his anatomy. The canvas is hardly bigger than a sheet of writing paper.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('aa4sbjjjav', 'daily:skull:1427-masaccio-holy-trinity', 'Holy Trinity', 'Masaccio', 1427, null, 'Early Renaissance', 'fresco', 'Santa Maria Novella, Florence', 3, 'object', 'https://nambatu.github.io/circart-preview/art/aa4sbjjjav.jpg', 'The painted barrel vault was so convincing that contemporaries described walking up to the wall to check whether the chapel was real. It is the first surviving painting built on a mathematically consistent one-point perspective scheme, executed just a few years after Brunelleschi worked out the system. At the bottom, a skeleton on a tomb carries an inscription telling the viewer that what you are, I once was, and what I am, you will be. Renaissance painting begins with a memento mori and a magic trick in the same picture.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('drdz63m2fb', 'daily:skull:1872-arnold-b-cklin-self-portrait-with-death-playing-the-fid', 'Self-Portrait with Death Playing the Fiddle', 'Arnold Böcklin', 1872, null, null, 'oil on canvas', 'Alte Nationalgalerie, Berlin', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/drdz63m2fb.jpg', 'Böcklin painted this in Munich and showed it there the same year. Alma Mahler said that her husband Gustav was under the spell of this picture when he wrote the scherzo of his Fourth Symphony.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('veeduuyz53', 'daily:skull:1521-albrecht-d-rer-saint-jerome', 'Saint Jerome', 'Albrecht Dürer', 1521, 'painted on Dürer''s journey to the Netherlands, 1520–21; finished in March 1521', null, 'oil on panel', 'Museu Nacional de Arte Antiga, Lisbon', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/veeduuyz53.jpg', 'For the saint''s face Dürer drew an old man he met in the Netherlands. The drawing is kept in Vienna today, and on it Dürer noted the man''s age: 93.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('e54qhj6vnt', 'daily:skull:1651-david-bailly-vanitas-still-life-with-portrait-of-a-yo', 'Vanitas Still Life with Portrait of a Young Painter', 'David Bailly', 1651, null, null, 'oil on panel', 'Museum De Lakenhal, Leiden', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/e54qhj6vnt.jpg', 'Behind the tall glass you can make out the faint face of a woman. The museum thinks she may be Bailly''s wife. This is the last work of his that we know.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de) values ('2026-11-15', 'skull', 'The skull on the table', 'Der Schädel auf dem Tisch', 'November is the month for remembering, and painters have always had a favourite way of doing it: they put a skull in the picture. It isn''t there to scare you. It is a small reminder that time is short, so enjoy it. Your start card is a Dutch table with a skull on it, and the first picture to place hides its skull so well that you could walk right past it.', 'Der November ist der Monat des Erinnerns, und Maler hatten dafür schon immer ein Lieblingsmittel: Sie malten einen Schädel ins Bild. Er soll dir keine Angst machen. Er erinnert nur freundlich daran, dass die Zeit kurz ist und du sie genießen sollst. Deine Startkarte ist ein holländischer Tisch mit einem Schädel darauf, und das erste Bild zum Einordnen versteckt seinen Schädel so gut, dass du glatt daran vorbeilaufen könntest.', 'Seven pictures, and not one of these skulls wanted to frighten you. Each one says the same friendly thing in its own voice: your time is precious. Critics of Böcklin''s day had a lovely name for that. They called it “memento vivere”, remember to live. That sounds like a good plan for a Sunday in November.', 'Sieben Bilder, und keiner dieser Schädel wollte dir Angst machen. Jeder sagt auf seine Art dasselbe Freundliche: Deine Zeit ist kostbar. Kritiker zu Böcklins Zeit hatten dafür einen schönen Namen. Sie nannten es „Memento vivere“, denk daran zu leben. Das klingt nach einem guten Plan für einen Sonntag im November.') on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 0, 'jz7qdrkayf', null, null, 'Pieter Claesz, public domain (Mauritshuis / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 1, 'xs8xx9jzr9', 'These two friends are still in their twenties, and they seem to have everything a person could wish for. Holbein gave them two secrets. One is the skull, which you only find when you walk to the right-hand edge of the picture. The other is a tiny crucifix that peeps out from behind the green curtain at the top left. Our next skull takes it all far less seriously: it is having a smoke.', 'Die beiden Freunde sind noch keine dreißig und scheinen alles zu haben, was man sich wünschen kann. Holbein hat ihnen zwei Geheimnisse mitgegeben. Das eine ist der Schädel, den du erst findest, wenn du an den rechten Bildrand gehst. Das andere ist ein winziges Kruzifix, das oben links hinter dem grünen Vorhang hervorschaut. Unser nächster Schädel nimmt das alles viel lockerer: Er raucht erst mal eine.', 'Hans Holbein the Younger, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 2, 'gh9mkbwkze', 'Van Gogh painted this while he was a student at the art academy in Antwerp. Drawing skeletons was a normal exercise there, but painting one with a cigarette was certainly not on the timetable. He loved to smoke himself, so this is a student''s joke and no warning at all. Our next skeleton has something to say to you. It lies at the foot of a church wall in Florence.', 'Van Gogh malte das Bild, als er an der Kunstakademie in Antwerpen studierte. Skelette zu zeichnen war dort eine ganz normale Übung, aber eines mit Zigarette zu malen stand sicher nicht auf dem Stundenplan. Er rauchte selbst leidenschaftlich gern, also ist das ein Studentenwitz und keine Warnung. Unser nächstes Skelett hat dir etwas zu sagen. Es liegt am Fuß einer Kirchenwand in Florenz.', 'Vincent van Gogh, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 3, 'aa4sbjjjav', 'This skeleton talks to everyone who walks past, and then it fell silent for a very long time. In 1570 Giorgio Vasari set a stone altar in front of the wall, and the whole fresco disappeared behind it. The skeleton was only found again under the plaster in 1952. Our next painter does not read about death. He hears it, because someone is playing the fiddle right behind him.', 'Dieses Skelett spricht jeden an, der vorbeigeht, und dann blieb es sehr lange stumm. 1570 stellte Giorgio Vasari einen Steinaltar vor die Wand, und das ganze Fresko verschwand dahinter. Das Skelett fand man erst 1952 unter dem Putz wieder. Unser nächster Maler liest nichts über den Tod. Er hört ihn, denn direkt hinter ihm spielt jemand Geige.', 'Masaccio, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 4, 'drdz63m2fb', 'Böcklin has stopped painting to listen. Behind him Death plays a fiddle that has only one string left. He doesn''t look frightened, more like someone who has just had an idea, and the museum in Berlin reads it exactly that way: Death is not his enemy here, he brings the inspiration. In our next picture an old man lays his finger on a skull and looks you straight in the eye.', 'Böcklin hält beim Malen inne und lauscht. Hinter ihm spielt der Tod auf einer Geige, die nur noch eine Saite hat. Erschrocken sieht er nicht aus, eher wie jemand, dem gerade etwas eingefallen ist, und genau so liest es auch das Museum in Berlin: Der Tod ist hier kein Feind, er bringt die Eingebung. Auf unserem nächsten Bild legt ein alter Mann den Finger auf einen Schädel und schaut dir direkt in die Augen.', 'Arnold Böcklin, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 5, 'veeduuyz53', 'The old man is Saint Jerome, the great scholar among the saints. He looks up from his books, and his finger on the skull asks you a quiet question: what are you doing with your time? Dürer painted him on a journey through the Netherlands and gave the picture to a Portuguese trade envoy there, which is why it hangs in Lisbon today. For our last picture a painter lays out his whole life on one table.', 'Der alte Mann ist der heilige Hieronymus, der große Gelehrte unter den Heiligen. Er blickt von seinen Büchern auf, und sein Finger auf dem Schädel stellt dir leise eine Frage: Was machst du mit deiner Zeit? Dürer malte ihn auf einer Reise durch die Niederlande und schenkte das Bild dort einem portugiesischen Handelsgesandten, und deshalb hängt es heute in Lissabon. Für unser letztes Bild breitet ein Maler sein ganzes Leben auf einem Tisch aus.', 'Albrecht Dürer, public domain (The Yorck Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 6, 'e54qhj6vnt', 'A young painter holds up a small oval portrait of an old man. The old man is David Bailly himself, and nobody knows for sure who the young one is. He may well be Bailly too, as he once looked. So one man meets himself across a table full of soap bubbles and coins, with a skull among them and a slip of paper that says everything is vanity.', 'Ein junger Maler hält ein kleines ovales Bildnis eines alten Mannes hoch. Der alte Mann ist David Bailly selbst, und wer der junge ist, weiß niemand genau. Gut möglich, dass auch er Bailly ist, so wie er einmal aussah. So begegnet ein Mann sich selbst an einem Tisch voller Seifenblasen und Münzen, mit einem Schädel dazwischen und einem Zettel, auf dem steht, dass alles eitel ist.', 'David Bailly, public domain (Museum De Lakenhal / Wikimedia Commons)');
